package cz.multio.doklady.ui

import androidx.compose.foundation.Image
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.layout.ContentScale
import cz.multio.doklady.platform.decodeImage
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

/** Logo Multio CZ (stejné jako na webu, PNG 640 × 252). Je přímo v kódu, aby fungovalo na Androidu i iPhonu bez dalších zdrojů. */
@OptIn(ExperimentalEncodingApi::class)
private val LOGO_PNG: ByteArray by lazy { Base64.decode(LOGO_B64) }

@Composable
fun BrandLogo(modifier: Modifier = Modifier) {
    val bitmap = remember { decodeImage(LOGO_PNG) }
    if (bitmap != null) {
        Image(bitmap, "Multio CZ s.r.o. – Poradce v oblasti účetnictví", modifier = modifier, contentScale = ContentScale.Fit)
    }
}

private const val LOGO_B64 = ""
